import{_ as i,o as t,c as a,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const h=JSON.parse('{"title":"Copy-ready remediation prompt: complete and harden Record References","description":"","frontmatter":{},"headers":[],"relativePath":"record-references/REMEDIATION_PROMPT.md","filePath":"record-references/REMEDIATION_PROMPT.md"}'),o={name:"record-references/REMEDIATION_PROMPT.md"};function n(l,e,s,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="copy-ready-remediation-prompt-complete-and-harden-record-references" tabindex="-1">Copy-ready remediation prompt: complete and harden Record References <a class="header-anchor" href="#copy-ready-remediation-prompt-complete-and-harden-record-references" aria-label="Permalink to &quot;Copy-ready remediation prompt: complete and harden Record References&quot;">​</a></h1><p>Continue the existing Record References implementation in <code>D:\\projects\\TagERP</code> and fix every verified gap below. This is a remediation task, not a greenfield rewrite. Preserve unrelated and user-owned changes, especially the currently uncommitted Dynamic Table and Dynamic Record View work. Do not revert, replace, or broadly redesign working subsystems unless a narrowly scoped refactor is required to meet the acceptance criteria.</p><p>Follow <code>AGENTS.md</code>, <code>CLAUDE.md</code>, <code>.ai/rules/index.md</code>, every path-matching project rule, and the relevant Laravel, Livewire, Flux UI, Tailwind CSS, and Pest skills. Confirm installed versions and use the project&#39;s version-specific documentation search before code changes. Do not add dependencies or edit files under <code>vendor/</code> without explicit user approval.</p><h2 id="existing-implementation-to-retain" tabindex="-1">Existing implementation to retain <a class="header-anchor" href="#existing-implementation-to-retain" aria-label="Permalink to &quot;Existing implementation to retain&quot;">​</a></h2><p>The following foundations already exist and must be improved rather than recreated:</p><ul><li>required allowlisted <code>applications.color</code> in the original create-table migration;</li><li><code>ApplicationColor</code>, <code>RecordReferencePalette</code>, DTOs, provider contract, registry, and resolver;</li><li>Country provider backed by the existing <code>Nnjeim\\World\\Models\\Country</code> model/table/data;</li><li>stateless Card, Tag, and Icon Blade variants;</li><li>one shared Livewire preview host in the app layout;</li><li>typed Dynamic Table <code>RecordReferenceColumn</code>;</li><li>Country Dynamic Record View show page and route;</li><li>Record Reference, Dynamic Table, Dynamic Record View, and Dynamic Form documentation;</li><li>current tests.</li></ul><p>Do not create a duplicate Country model, countries table migration, Country seed dataset, or custom replacement for the <code>nnjeim/world</code> package. Do not create a second color migration. Keep all current Application color mappings and strengthen their regression coverage where needed.</p><h2 id="verified-defects-to-fix" tabindex="-1">Verified defects to fix <a class="header-anchor" href="#verified-defects-to-fix" aria-label="Permalink to &quot;Verified defects to fix&quot;">​</a></h2><ol><li><code>resources/views/components/dynamic-table/table.blade.php</code> queries Applications from Blade.</li><li>Every rendered Country identity calls <code>CountryRecordReferenceProvider::authorize()</code>, which queries the Application again, causing an N+1 during the Blade render. Existing query-count tests measure <code>paginate()</code> only and miss rendering.</li><li>Hidden Record Reference columns can still trigger the Application metadata query because codes are collected from all definitions, not only visible authorized columns.</li><li>Related Tag/Icon references use unconstrained <code>with($path)</code>, loading complete related rows and preview-only fields before user action.</li><li>Preview authorization checks only Application <code>is_active</code>; it does not consistently enforce authenticated user, <code>permission_name</code>, tenant/parent scope, Country status, or the same access rule used by the show route.</li><li>The Country show route is authenticated but its record query is otherwise unscoped.</li><li>Unauthorized identities still render record metadata and <code>href=&quot;&quot;</code>; the link is not actually omitted.</li><li>The preview cache key is only <code>applicationCode:recordKey</code>; it omits version, locale, and access scope.</li><li>Preview actions have no abuse/rate guard and rejected client promises can leave in-flight/loading state stuck.</li><li>Tag markup nests a button inside an anchor. Icon touch behavior may preview and navigate from the same gesture. Hit targets, translations, focus restoration, and viewport collision handling are incomplete.</li><li>The seeded Application route <code>general.world.countries</code> has no real application index route/page; only <code>general.world.countries.show</code> exists.</li><li>Dynamic Table has a typed column but no real production Country index table uses it.</li><li>Dynamic Record View has no typed Record Reference field/content integration.</li><li>Dynamic Form does not exist. Documentation correctly admits that, but no code may claim that its integration is delivered.</li><li><code>.ai/dynamic-table/CHECKLIST.md</code> contradicts itself by marking the integration both DONE and PLANNED and claims hidden-column tests that do not exist.</li><li>The full test suite is not stable: 257/258 passed during audit, with <code>FilterOperatorUiTest</code> failing in the full run but passing by itself, indicating order-dependent state or test isolation.</li></ol><h2 id="required-outcomes" tabindex="-1">Required outcomes <a class="header-anchor" href="#required-outcomes" aria-label="Permalink to &quot;Required outcomes&quot;">​</a></h2><h3 id="_1-create-one-query-free-access-and-metadata-boundary" tabindex="-1">1. Create one query-free access and metadata boundary <a class="header-anchor" href="#_1-create-one-query-free-access-and-metadata-boundary" aria-label="Permalink to &quot;1. Create one query-free access and metadata boundary&quot;">​</a></h3><p>Move every database query out of Blade. Introduce or reuse a focused service/presenter that prepares Record Reference render data before views receive it.</p><p>The implementation must:</p><ul><li>resolve all distinct <strong>visible and authorized</strong> Application codes in one bounded query or trusted cross-request navigation/application metadata cache;</li><li>select only required Application metadata (<code>id</code>, <code>code</code>, translated name fields, <code>icon</code>, <code>color</code>, <code>is_active</code>, <code>permission_name</code>, and required ownership keys);</li><li>memoize access decisions per Application/current actor/tenant for the current request;</li><li>enforce <code>is_active</code> and <code>permission_name</code> consistently with <code>NavigationTreeService</code>;</li><li>avoid any policy or Application query inside a per-row loop;</li><li>keep record-level authorization pure/query-free when evaluating an already-loaded row;</li><li>return <code>null</code>/an unavailable DTO for unauthorized identity instead of a DTO containing title/facts with a null URL;</li><li>ensure views receive prepared identities/facts only and contain no Eloquent or registry queries.</li></ul><p>Prefer one explicit public service/contract over static state. Do not store user-specific authorization inside the global registry or a process-lifetime singleton. The provider registry itself is stateless; fix its binding/registration lifecycle so it works correctly under normal PHP requests and long-lived workers. A scoped registry whose instance is flushed while module <code>boot()</code> does not rerun is not an acceptable Octane-safe design.</p><h3 id="_2-enforce-one-authorization-rule-everywhere" tabindex="-1">2. Enforce one authorization rule everywhere <a class="header-anchor" href="#_2-enforce-one-authorization-rule-everywhere" aria-label="Permalink to &quot;2. Enforce one authorization rule everywhere&quot;">​</a></h3><p>Preview, initial Card/Tag/Icon render, Dynamic Table, Countries index, and Country show route must use the same access boundary.</p><p>At minimum:</p><ul><li>require an authenticated user for all Record Reference preview actions in this authenticated ERP;</li><li>deny an inactive Application;</li><li>enforce <code>permission_name</code> when present and fail closed if permission evaluation errors;</li><li>apply tenant and parent scopes when a provider declares them;</li><li>define and test the intended Country record-status rule; unless an existing product rule says otherwise, only <code>status = 1</code> Countries are referenceable/showable;</li><li>return the same generic unavailable/not-found behavior without leaking whether a denied record exists;</li><li>generate URLs server-side through named routes;</li><li>never expose title, URL, facts, or stale cached facts for a denied identity;</li><li>render no anchor when URL is absent. Use a non-interactive semantic element or render nothing, according to the caller&#39;s documented behavior. Never use <code>href=&quot;&quot;</code> as an authorization fallback.</li></ul><p>Add tests for guest preview attempts, authenticated users without required permission, inactive Application, inactive Country, missing Country, forged Application code, cross-tenant/parent fixtures where the project has such context, and consistency between preview and show-route access.</p><h3 id="_3-remove-n-1-and-prove-the-complete-render-budget" tabindex="-1">3. Remove N+1 and prove the complete render budget <a class="header-anchor" href="#_3-remove-n-1-and-prove-the-complete-render-budget" aria-label="Permalink to &quot;3. Remove N+1 and prove the complete render budget&quot;">​</a></h3><p>Fix Country authorization so it never queries the Application for each row. Move Application loading and access evaluation outside the row loop.</p><p>Add end-to-end query-count tests that render the actual Dynamic Table/Blade/Livewire output, not only <code>TableQueryBuilder::paginate()</code>:</p><ul><li>render 10 and 50 Tag rows and assert the same query count;</li><li>render 10 and 50 Card rows and assert the same query count;</li><li>assert there is no Application query per row;</li><li>assert a hidden Record Reference column performs no Application metadata query and adds no record select/eager load;</li><li>assert multiple visible columns for one Application deduplicate metadata and relation requirements;</li><li>keep existing pagination count/data query assertions.</li></ul><p>No queries may occur from Blade, a formatter, DTO, accessor used by rendering, or provider fact/title methods. Enable lazy-loading prevention in the relevant tests so undeclared relationships fail loudly.</p><h3 id="_4-make-lazy-loading-correct-for-self-and-related-references" tabindex="-1">4. Make lazy loading correct for self and related references <a class="header-anchor" href="#_4-make-lazy-loading-correct-for-self-and-related-references" aria-label="Permalink to &quot;4. Make lazy loading correct for self and related references&quot;">​</a></h3><p>Refine the provider/query requirement contract so columns and relations are explicit and cannot be confused. Support separate requirements for:</p><ul><li>initial identity columns/relations;</li><li>immediately visible Card columns/relations;</li><li>on-demand preview columns/relations.</li></ul><p>For Tag/Icon:</p><ul><li>initial self-reference queries select identity only;</li><li>initial belongs-to reference eager loads select only related primary/owner keys plus identity fields;</li><li>preview-only fields and relations must not appear in initial SQL or loaded attributes;</li><li>no <code>SELECT *</code> related eager load is allowed.</li></ul><p>For Card:</p><ul><li>include only identity and Card-visible requirements in the existing bounded page query;</li><li>do not issue per-card requests or queries.</li></ul><p>For Preview:</p><ul><li>load only identity plus preview requirements after the deliberate user action;</li><li>constrain relation selects while retaining every Eloquent key needed to hydrate relationships;</li><li>merge and deduplicate identical requirements;</li><li>explicitly reject unsupported relation types/depths with configuration exceptions rather than silently falling back to full-row loading.</li></ul><p>Validate that a <code>RecordReferenceColumn</code>&#39;s resolved record model matches the provider&#39;s model class. Add self-reference, belongs-to, hidden-column, Card, Tag, and Icon SQL/loaded-attribute tests.</p><h3 id="_5-correct-preview-caching-deduplication-and-abuse-controls" tabindex="-1">5. Correct preview caching, deduplication, and abuse controls <a class="header-anchor" href="#_5-correct-preview-caching-deduplication-and-abuse-controls" aria-label="Permalink to &quot;5. Correct preview caching, deduplication, and abuse controls&quot;">​</a></h3><p>Add a provider-owned record version contract. Use <code>updated_at</code> where reliable. For timestamp-less, mostly immutable package records such as Country, define an explicit reliable dataset/version token or disable reusable caching if no correct version can be supplied; do not pretend an ID alone is a version.</p><p>The page-memory cache and in-flight key must include:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>application code + record key + record version + locale + tenant/access scope</span></span></code></pre></div><p>Requirements:</p><ul><li>reopening the same authorized version in the same page makes zero new Livewire/HTTP requests;</li><li>a version, locale, user/tenant, permission, or selected-record change cannot reuse stale preview;</li><li>failed/rejected requests clear loading and in-flight state via <code>try/finally</code> and show a generic safe error state;</li><li>cancel delayed hover before the request if the pointer leaves;</li><li>add a bounded per-user/session/IP preview rate guard using project/Laravel conventions without weakening Livewire CSRF/session protections;</li><li>keep cross-request fact caching disabled by default; if any provider opts in, include all access and version dimensions and implement invalidation.</li></ul><p>Do not preload adjacent/visible previews and do not serialize facts into initial DOM attributes, Alpine state, or Livewire public state.</p><h3 id="_6-repair-the-three-ui-variants" tabindex="-1">6. Repair the three UI variants <a class="header-anchor" href="#_6-repair-the-three-ui-variants" aria-label="Permalink to &quot;6. Repair the three UI variants&quot;">​</a></h3><p>Keep the existing visual direction and Application palette, but fix semantics and accessibility.</p><p>Card:</p><ul><li>valid link semantics with no nested controls;</li><li>non-link fallback when URL is absent;</li><li>two-to-four prioritized, translated facts;</li><li>long-title truncation/wrapping, RTL, dark mode, contrast, and focus-visible states.</li></ul><p>Tag:</p><ul><li>do not nest a button inside an anchor;</li><li>use sibling navigation and preview controls within a semantic wrapper, or another valid accessible structure;</li><li>preserve left/primary navigation plus right-click, Context Menu key/<code>Shift+F10</code>, and a discoverable touch preview action;</li><li>ensure triggering preview never accidentally navigates.</li></ul><p>Icon:</p><ul><li>keep the visual icon-only requirement;</li><li>provide at least a 44x44 CSS-pixel interactive hit target;</li><li>make desktop primary activation and touch preview/navigation behavior unambiguous;</li><li>do not open a preview and navigate from the same gesture;</li><li>provide an accessible name and keyboard access without hover dependency.</li></ul><p>Preview surface:</p><ul><li>use Flux free components where appropriate; do not use Pro-only components;</li><li>translate every visible/ARIA string through Laravel localization;</li><li>position relative to the actual triggering anchor, clamp horizontally/vertically, and flip above when there is insufficient space below;</li><li>use the event&#39;s anchor for correct focus restoration;</li><li>close on Escape and outside activation;</li><li>handle reduced motion and loading/unavailable/error states;</li><li>avoid layout shift in tables.</li></ul><p>Add Blade rendering tests for valid unauthorized markup and escaping. If Pest Browser is configured, add browser tests for navigation, right click, keyboard, focus restoration, touch behavior, request deduplication, dark mode, RTL, and viewport edges. If it is not configured, do not add a dependency; perform the equivalent manual in-app browser verification and document exact evidence and any remaining unautomated risk.</p><h3 id="_7-deliver-a-real-countries-index-using-dynamic-table" tabindex="-1">7. Deliver a real Countries index using Dynamic Table <a class="header-anchor" href="#_7-deliver-a-real-countries-index-using-dynamic-table" aria-label="Permalink to &quot;7. Deliver a real Countries index using Dynamic Table&quot;">​</a></h3><p>Create the missing application-owned Countries index route/page named exactly <code>general.world.countries</code>, matching <code>WorldApplicationsSeeder</code>. Reuse the package Country model/table and the existing Dynamic Table engine.</p><p>The real Countries table must:</p><ul><li>be authenticated and use the same Application/record access boundary;</li><li>be paginated and explicitly select required columns;</li><li>use <code>RecordReferenceColumn</code> in a real production definition, not tests only;</li><li>default to the most appropriate compact variant (normally Tag), link to <code>general.world.countries.show</code>, and expose the configured important facts lazily;</li><li>provide explicit scalar search/sort/filter fields without trusting browser SQL/relations;</li><li>avoid loading all Countries or preview facts upfront;</li><li>make the seeded launcher Application route resolve to a real URL.</li></ul><p>Add route, Livewire, authorization, query-count, search/sort/pagination, and record-link tests.</p><h3 id="_8-add-dynamic-record-view-integration-honestly" tabindex="-1">8. Add Dynamic Record View integration honestly <a class="header-anchor" href="#_8-add-dynamic-record-view-integration-honestly" aria-label="Permalink to &quot;8. Add Dynamic Record View integration honestly&quot;">​</a></h3><p>Add a typed, reusable Record Reference field/content type to the existing Dynamic Record View engine so a definition can declaratively render an already-loaded record/relation as Card, Tag, or Icon.</p><p>It must:</p><ul><li>depend only on the shared Record Reference contracts, not Dynamic Table internals;</li><li>accept a trusted Application code, variant, and record/relation source declared server-side;</li><li>reuse the same resolver/access service and shared preview host;</li><li>declare/merge query requirements before rendering;</li><li>never query from the field Blade view;</li><li>expose no complete model in public Livewire state;</li><li>render safe missing/unauthorized states;</li><li>include unit, feature, and query-count tests plus documentation/example usage.</li></ul><p>Do not force an artificial Country-to-Country relation merely to demonstrate it. Use an existing real relation that semantically fits, or a focused test definition if no real current screen is appropriate.</p><h3 id="_9-keep-dynamic-form-status-truthful" tabindex="-1">9. Keep Dynamic Form status truthful <a class="header-anchor" href="#_9-keep-dynamic-form-status-truthful" aria-label="Permalink to &quot;9. Keep Dynamic Form status truthful&quot;">​</a></h3><p>Confirm again whether a real shared Dynamic Form engine exists.</p><ul><li>If it now exists, add a typed <code>RecordReferenceField</code> following its actual conventions and test all three variants, scalar hydration/dehydration, authorization, relation changes, validation rerenders, lazy preview, and stale-preview invalidation.</li><li>If it still does not exist, do <strong>not</strong> invent a partial/fake form framework as part of this fix. Keep <code>docs/dynamic-form/record-references.md</code> as an explicit future contract, ensure the shared Record Reference API has no Dynamic Table/View coupling that would block it, and do not mark Dynamic Form integration complete anywhere.</li></ul><p>The final report must clearly distinguish “form-ready shared API” from “implemented Dynamic Form field.”</p><h3 id="_10-stabilize-tests-and-correct-documentation" tabindex="-1">10. Stabilize tests and correct documentation <a class="header-anchor" href="#_10-stabilize-tests-and-correct-documentation" aria-label="Permalink to &quot;10. Stabilize tests and correct documentation&quot;">​</a></h3><p>Diagnose the full-suite-only failure in <code>tests/Feature/DynamicTable/FilterOperatorUiTest.php</code>. Fix the underlying leaked state, duplicate component registration, database/cache state, static data, or test isolation issue. Do not weaken or skip the assertion and do not hide the failure with retries.</p><p>Correct documentation after code is verified:</p><ul><li>remove the contradictory DONE/PLANNED Record Reference sections in <code>.ai/dynamic-table/CHECKLIST.md</code> and keep one truthful checklist;</li><li>do not claim hidden-column, browser, authorization, or relation-select coverage unless the tests actually exist;</li><li>update <code>docs/record-references/README.md</code> with final namespaces, access flow, cache key/version rules, real measured query/request budgets, Countries index usage, UI behavior, and limitations;</li><li>update <code>docs/dynamic-table/record-references.md</code> and Dynamic Record View docs with working examples;</li><li>keep Dynamic Form documentation explicitly planned if no engine exists;</li><li>preserve <code>IMPLEMENTATION_PROMPT.md</code> as historical scope and add a short reference to this remediation document rather than rewriting history.</li></ul><h2 id="mandatory-tests" tabindex="-1">Mandatory tests <a class="header-anchor" href="#mandatory-tests" aria-label="Permalink to &quot;Mandatory tests&quot;">​</a></h2><p>Add or correct tests proving all of the following:</p><ul><li>guest/permission/inactive Application/inactive Country/missing/forged preview denial with no data;</li><li>the same access result for initial render, preview, Countries index, and Country show route;</li><li>unauthorized variants contain no title/facts/link and never <code>href=&quot;&quot;</code>;</li><li>no queries in Blade and no per-row authorization/Application queries;</li><li>actual Livewire/Blade render query count is constant for 10 versus 50 rows;</li><li>hidden references cause zero metadata/select/eager-load work;</li><li>self and belongs-to Tag/Icon initial SQL omits preview data;</li><li>Card includes only visible Card requirements;</li><li>preview loads only declared fields/relations after action;</li><li>cache/in-flight keys vary by version, locale, and access scope;</li><li>repeat preview reuses the result; changed version/locale/access does not;</li><li>rate guard fails safely;</li><li>valid Card/Tag/Icon HTML, escaping, translations, keyboard/touch behavior, focus, RTL/dark mode, and viewport positioning to the extent supported by installed test tooling;</li><li>real <code>general.world.countries</code> index route and table behavior;</li><li>Dynamic Record View typed Record Reference integration;</li><li>Dynamic Form tests only if a real engine exists;</li><li>the previously order-dependent FilterOperator UI test is stable in the full suite.</li></ul><p>Do not delete existing tests. Correct tests whose names currently contradict their assertions, such as the “omits the link” test expecting <code>href=&quot;&quot;</code>.</p><h2 id="verification-sequence" tabindex="-1">Verification sequence <a class="header-anchor" href="#verification-sequence" aria-label="Permalink to &quot;Verification sequence&quot;">​</a></h2><ol><li>Run focused security/access tests.</li><li>Run Record Reference unit and feature tests.</li><li>Run Dynamic Table unit and feature tests.</li><li>Run Dynamic Record View unit and feature tests.</li><li>Run World Application seeder tests.</li><li>Run the previously flaky FilterOperator UI file with relevant neighboring suites in both orders.</li><li>Run <code>vendor/bin/pint --dirty --format agent</code> after PHP changes.</li><li>Run <code>php artisan test --compact</code> at least twice from a clean test state. Both runs must pass without retries, skips, or order-dependent failures.</li><li>Build frontend assets if compiled CSS/JS inputs changed.</li><li>Perform real-browser verification of Card/Tag/Icon interactions where tooling is available and check recent browser console logs.</li></ol><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><p>Do not report this remediation complete until:</p><ul><li>Blade performs zero database queries;</li><li>query counts remain constant through the complete render, not only pagination;</li><li>related Tag/Icon references do not preload preview data;</li><li>all initial/preview/show/index authorization paths agree and fail closed;</li><li>denied references leak no title, URL, facts, or existence signal;</li><li>no unauthorized fallback emits <code>href=&quot;&quot;</code>;</li><li>cache reuse is correctly scoped and versioned;</li><li>Card/Tag/Icon markup and touch/keyboard behavior are valid and verified;</li><li><code>general.world.countries</code> is a real working Dynamic Table page;</li><li>Dynamic Record View has a typed Record Reference integration;</li><li>Dynamic Form is either genuinely integrated or still labeled planned—never falsely complete;</li><li>documentation/checklists match the delivered code and tests;</li><li>the entire project suite passes twice consecutively;</li><li>the final handoff reports exact changed files, measured query/request counts, test totals, browser evidence, remaining limitations, and any consciously deferred work.</li></ul>',80)])])}const m=i(o,[["render",n]]);export{h as __pageData,m as default};
